const route=useRoute(),router=useRouter(),navigateView=createViewNavigation(router)
const protocol=ref(route.query.protocol==='dubbo'?'dubbo':'http')
const environments=ref([]),environment=ref('__all'),view=ref('documents'),requestMime=ref(''),group=ref(String(route.query.group||''))
const services=ref([]),snapshots=ref([]),document=ref(null),selected=ref(null),loading=ref(false),detailLoading=ref(false),saving=ref(false),importing=ref(false),me=ref(null),providers=ref([])
const service=ref(''),snapshot=ref(null),search=ref(String(route.query.q||'')),sourceOpen=ref(false),source=ref({provider:'',revision:0,required:false,on_build:false,settings:{}}),fields=ref([]),schemaLoading=ref(false)
const admin=computed(()=>me.value?.role==='admin'),current=computed(()=>snapshots.value.find(v=>v.id===snapshot.value)||document.value?.snapshot)
const groups=computed(()=>[...new Set((document.value?.operations||[]).flatMap(o=>o.tags||[]))].sort())
const operations=computed(()=>(document.value?.operations||[]).filter(o=>operationMatches(o,search.value,group.value)&&(!maintainer.value||[o.maintainer,o.maintainer_name].join(' ').toLowerCase().includes(maintainer.value.toLowerCase()))))
const documentContent=ref(null)
const maintainer=ref(String(route.query.maintainer||'')),editingDoc=ref(false),documentEditor=ref(null),editorState=ref({dirty:false,busy:false})
const browseLatest=ref(!route.query.snapshot||route.query.latest==='1'),searchRevision=ref(0)
const latestList=computed(()=>!service.value||view.value==='documents'&&browseLatest.value)
let epoch=0,schemaEpoch=0
async function api(path,options){const r=await fetch(path,options);const raw=await r.text();let body;try{body=JSON.parse(raw)}catch{body={}}if(body?.document&&body?.operations)body.document_text=documentTextFromResponse(raw);if(!r.ok||body.error)throw Error(body.error?.message||body.error||'请求失败');return body}
const query=()=>'?'+new URLSearchParams({protocol:protocol.value,service:service.value,...(environment.value==='__all'?{}:{environment:environment.value==='__unassigned'?'':environment.value})})
const environmentOptions=computed(()=>[{value:'__all',label:'全部环境'},{value:'__unassigned',label:'未区分环境（历史）'},...environments.value.map(e=>({value:e.name,label:e.display_name||e.name}))])
const concreteEnvironment=computed(()=>environment.value&&!environment.value.startsWith('__'))
const detailService=computed(()=>document.value?.snapshot?.service||service.value)
const detailEnvironment=computed(()=>environments.value.find(e=>e.name===current.value?.environment)?.display_name||current.value?.environment||'未区分环境')
const detailApplication=computed(()=>services.value.find(s=>s.name===detailService.value)?.display_name||detailService.value)
function syncRoute(push=false){window.document.title='接口文档'+(service.value?' · '+service.value:'');navigateView({path:'/documents',query:{...(protocol.value==='dubbo'?{protocol:'dubbo'}:{}),...(service.value?{service:service.value}:{}),environment:environment.value,...(route.query.work_item?{work_item:route.query.work_item}:{}),...(view.value==='history'&&route.query.base_id?{base_id:route.query.base_id}:{}),...(search.value?{q:search.value}:{}),...(group.value?{group:group.value}:{}),...(maintainer.value?{maintainer:maintainer.value}:{}),...(service.value&&view.value!=='documents'?{tab:view.value}:{}),...(service.value&&browseLatest.value&&selected.value?{latest:'1'}:{}),...(snapshot.value&&(!browseLatest.value||selected.value)?{snapshot:String(snapshot.value)}:{}),...(selected.value?{detail_service:detailService.value,detail_environment:current.value?.environment||'',detail_protocol:protocol.value}:{}),...(selected.value?{operation:selected.value.id}:{})}},push);if(window.parent!==window)window.parent.postMessage({type:'workspace.label',label:'接口文档'+((detailService.value||service.value)?' · '+(detailApplication.value||service.value):'')+(selected.value?' · '+detailEnvironment.value+' · 文档 #'+snapshot.value:'')},location.origin)}
async function openSearchResult(row,mode='view',push=true){
 const revision=++epoch;detailLoading.value=true
 try{
  const q=new URLSearchParams({service:row.service});if(row.environment!==undefined)q.set('environment',row.environment)
  const data=await api('api/api-documents/'+encodeURIComponent(row.snapshot_id)+'?'+q)
  if(revision!==epoch||service.value&&service.value!==row.service)return
  const operation=data.operations.find(o=>o.id===row.id);if(!operation)throw Error('接口已不在此文档快照中，请刷新检索结果')
  document.value=data;snapshot.value=data.id
  if(mode==='view'){selected.value=operation;syncRoute(push)}else{openTesting(operation,mode);document.value=null;snapshot.value=null}
 }catch(e){if(revision===epoch)toast(e.message,'error')}finally{if(revision===epoch)detailLoading.value=false}
}
async function selectService(value){epoch++;sourceOpen.value=false;service.value=value;browseLatest.value=true;snapshot.value=null;document.value=null;selected.value=null;snapshots.value=[];detailLoading.value=false;view.value='documents';syncRoute(true);await loadSnapshots()}
async function selectProtocol(value){protocol.value=value;group.value='';await selectService(service.value)}
async function selectEnvironment(value){epoch++;sourceOpen.value=false;environment.value=value;browseLatest.value=true;snapshot.value=null;document.value=null;selected.value=null;snapshots.value=[];detailLoading.value=false;syncRoute(true);await loadSnapshots()}
async function showHistorySnapshot(id,operation){browseLatest.value=false;snapshot.value=id;view.value='documents';await loadDocument(operation,false);if(operation)selected.value=document.value?.operations.find(o=>o.id===operation)||null;syncRoute(true)}
async function loadSnapshots(preferred,operationID=route.query.operation){if(!service.value)return;const revision=++epoch;loading.value=true;try{const list=await api('api/api-documents'+query());if(revision!==epoch)return;snapshots.value=list;snapshot.value=Number(preferred)||list[0]?.id||null;if(!browseLatest.value||operationID)await loadDocument(operationID);else syncRoute()}catch(e){if(revision===epoch){snapshots.value=[];document.value=null;toast(e.message,'error')}}finally{if(revision===epoch)loading.value=false}}
async function loadDocument(operationID=route.query.operation,sync=true){document.value=null;selected.value=null;if(!snapshot.value){syncRoute();return}const revision=epoch,id=snapshot.value;detailLoading.value=true;try{const data=await api('api/api-documents/'+id+query());if(revision===epoch&&id===snapshot.value){document.value=data;if(data.snapshot&&!snapshots.value.some(v=>v.id===data.id))snapshots.value=[data.snapshot,...snapshots.value];selected.value=data.operations.find(o=>o.id===operationID)||null}}catch(e){toast(e.message,'error')}finally{if(revision===epoch&&id===snapshot.value){detailLoading.value=false;if(sync)syncRoute()}}}
async function importFile(file){
 if(!service.value||!concreteEnvironment.value)return toast('请选择文档归属应用和具体环境','warning')
 if(importing.value)return false
 importing.value=true
 const reportID=randomUUID().replaceAll('-',''),app=service.value,env=environment.value
 lastReport.value={id:reportID,service:app,environment:env,state:'processing',created_at:Math.floor(Date.now()/1000)}
 try{
  if(file.size>8*1024*1024)throw Error('文档不能超过 8 MiB')
  const result=await api('api/api-documents/import'+query()+'&report_id='+reportID,{method:'POST',headers:{'Content-Type':'application/json'},body:await file.text()})
  lastReport.value=result.report;protocol.value=result.protocol||protocol.value
  await loadSnapshots(result.report?.current_id||result.id);searchRevision.value++
  toast(result.report?.state==='historical'?'内容匹配历史版本，当前文档未更新':result.report?.state==='unchanged'?'上报成功，内容与当前文档一致':'上报成功，文档已保存','success')
 }catch(e){
  try{const data=await api('api/api-document-reports/'+reportID);lastReport.value=data.report}catch{lastReport.value={...lastReport.value,state:'uncertain',error:'未取得保存回执，请查询原上报记录'}}
  toast(e.message,'error')
 }finally{importing.value=false}
 return false
}
function openReport(id){openDocumentWorkspace('#/reports?'+new URLSearchParams({service:lastReport.value?.service||detailService.value,environment:lastReport.value?.environment||current.value?.environment||'',...(id?{report:id}:{})}))}

async function providerSchema(provider){const token=++schemaEpoch,app=service.value;fields.value=[];if(!provider){schemaLoading.value=false;return}const chosen=provider,tool=source.value.build_tool||services.value.find(s=>s.name===app)?.build_tool;schemaLoading.value=true;try{const out=await api('/api/extensions/'+encodeURIComponent(provider)+'/invoke',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({capability:'api.document.generate.v1',operation:'schema',input:{tool}})});if(token!==schemaEpoch||service.value!==app||source.value.provider!==chosen)return;fields.value=out.data.fields||[];for(const f of fields.value)if(source.value.settings[f.key]==null)source.value.settings[f.key]=f.default||''}catch(e){if(token===schemaEpoch)toast(e.message,'error')}finally{if(token===schemaEpoch)schemaLoading.value=false}}
async function openSource(){if(!service.value||!concreteEnvironment.value)return toast('请选择文档归属应用和具体环境','warning');try{const [config,list]=await Promise.all([api('api/api-documents/source'+query()),api('/api/extensions')]);source.value={...config,settings:config.settings||{}};providers.value=list.filter(p=>p.manifest.capabilities.includes('api.document.generate.v1'));sourceOpen.value=true;await providerSchema(source.value.provider)}catch(e){toast(e.message,'error')}}
async function changeProvider(value){source.value.provider=value;source.value.settings={};source.value.on_build=!!value&&source.value.default_on_build===true;await providerSchema(value)}
async function saveSource(){if(saving.value)return;if(fields.value.some(f=>f.required&&!source.value.settings[f.key]?.trim()))return toast('请填写完整的文档来源配置','warning');saving.value=true;try{source.value=await api('api/api-documents/source'+query(),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(source.value)});sourceOpen.value=false;toast('当前环境文档来源已保存，后续构建和编排引用此配置','success')}catch(e){toast(e.message,'error')}finally{saving.value=false}}
function openTesting(operation,mode='test-execution'){const hash='#/'+mode+'?protocol='+protocol.value+'&service='+encodeURIComponent(detailService.value)+'&environment='+encodeURIComponent(current.value?.environment||'')+'&snapshot='+snapshot.value+'&operation='+encodeURIComponent(operation.id);if(window.parent!==window){if(service.value)window.parent.postMessage({type:'context.update',service:detailService.value},location.origin);window.parent.postMessage({type:'workspace.open',plugin:'api-center',hash},location.origin)}else window.open(location.pathname+hash,'_blank','noopener')}
const definition=computed(()=>selected.value?operationAt(contract.value,selected.value.id)||selected.value.definition||{}:{})
const contract=computed(()=>document.value?.document_text?parseDocumentText(document.value.document_text):document.value?.document||{})
const parameters=computed(()=>selected.value?operationParameters({...selected.value,definition:definition.value},contract.value).map((p,i)=>({key:p.in+':'+p.name,field:p.name,field_path:'/'+p.name.replace(/~/g,'~0').replace(/\//g,'~1'),type:resolveSchema(p.schema,contract.value).type||'—',required:p.required||p.in==='path'?'是':'否',description:p.description||'—',in:p.in,...schemaMetadata(p.schema,contract.value),details:metadataText(schemaMetadata(p.schema,contract.value))})):[])
const parameterSchema=computed(()=>({type:'object',properties:Object.fromEntries(operationParameters({...selected.value,definition:definition.value},contract.value).map(p=>[p.in+':'+p.name,p.schema||{}]))}))
const requestContent=computed(()=>resolveSchema(definition.value.requestBody,contract.value).content||{})
const requestMedia=computed(()=>requestContent.value[requestMime.value]||{})
const requestRows=computed(()=>withMetadata(schemaRows(requestMedia.value.schema,contract.value)))
watch(selected,()=>{requestMime.value=Object.keys(requestContent.value)[0]||''})
const responseContent=computed(()=>Object.entries(definition.value.responses||{}).map(([status,value])=>({status,...resolveSchema(value,contract.value)})))
function metadataText(v){return [v.defaultValue!=='—'?'默认 '+v.defaultValue:'',v.enumValue!=='—'?'枚举 '+v.enumValue:'',v.constraints!=='—'?v.constraints:''].filter(Boolean).join('；')||'—'}
function withMetadata(rows){return rows.map(r=>({...r,details:metadataText(r),...(r.children?{children:withMetadata(r.children)}:{})}))}
function showOperation(record){selected.value=record;syncRoute(true)}
async function closeOperation(){if(editingDoc.value&&documentEditor.value&&!await documentEditor.value.canClose())return;editingDoc.value=false;editorState.value={dirty:false,busy:false};const previous=router.options.history.state.back;if(typeof previous==='string'){const u=new URL(previous,location.origin);if(u.pathname==='/documents'&&!u.searchParams.has('operation')){router.back();return}}epoch++;detailLoading.value=false;selected.value=null;if(!service.value){document.value=null;snapshot.value=null}syncRoute()}
const fieldSources=computed(()=>{const added=(document.value?.field_additions||[]).filter(f=>f.operation===selected.value?.id);const origins=Object.values(document.value?.lineage?.origins||{}).filter(v=>v.entity_kind==='field'&&v.operation===selected.value?.id);return origins.length?origins.map(v=>({...v.field,work_item:v.introduced_by,first_snapshot:v.first_snapshot,is_added:added.some(f=>f.operation===v.operation&&f.in===v.field.in&&f.status===v.field.status&&f.media===v.field.media&&f.field_path===v.field.field_path)})):added.map(f=>({...f,is_added:true}))})
const addedFields=computed(()=>(document.value?.field_additions||[]).filter(f=>f.operation===selected.value?.id))
function fieldChanges(location,status='',media=''){return fieldSources.value.filter(f=>(!location||f.in===location)&&(!status||f.status===status)&&(!media||f.media===media))}
const displayURL=computed(()=>selected.value?interfaceURL(contract.value,selected.value):'')
function copyInterfaceURL(){return copyText(displayURL.value,{successMessage:/^https?:\/\//.test(displayURL.value)?'接口 URL 已复制':'接口路径已复制（文档未声明完整服务器地址）'})}
function copyCurrentDocument(){const text=currentDocumentText(documentContent.value,{title:selected.value?.summary||selected.value?.path||''});if(!text)return toast('当前没有可复制的文档内容','warning');return copyText(text,{successMessage:'当前显示的文档内容已复制'})}
async function documentSaved(result){if(result.report)lastReport.value=result.report;
 const app=detailService.value,env=current.value.environment,op=selected.value.id
 editingDoc.value=false;editorState.value={dirty:false,busy:false}
 try{const data=await api('api/api-documents/'+result.id+'?'+new URLSearchParams({service:app,environment:env}));document.value=data;snapshot.value=data.id;selected.value=data.operations.find(v=>v.id===op)||data.operations[0]||null;if(service.value)snapshots.value=[data.snapshot,...snapshots.value.filter(v=>v.id!==data.id)];searchRevision.value++;syncRoute()}catch(e){toast('文档保存已返回，详情刷新失败，请核对版本；'+e.message,'error')}
}
const removeNavigationGuard=router.beforeEach(async(to,from)=>{
 if(to.fullPath===from.fullPath)return true
 if(saving.value||editorState.value.busy||sourceOpen.value)return false
