watch([sourceOpen,saving,editorState],([sourceDirty,sourceBusy,state])=>{if(window.parent!==window)window.parent.postMessage({type:'workspace.dirty',dirty:sourceDirty||state.dirty,busy:sourceBusy||state.busy},location.origin)})
watch(()=>route.query,async q=>{if(editingDoc.value){syncRoute();return}if(!services.value.length||saving.value||sourceOpen.value)return;const nextProtocol=q.protocol==='dubbo'?'dubbo':'http';const protocolChanged=nextProtocol!==protocol.value;protocol.value=nextProtocol;const app=!q.service?'':services.value.some(s=>s.name===q.service)?q.service:service.value;const env=environmentOptions.value.some(e=>e.value===q.environment)?q.environment:environment.value;const tab=['history','impact'].includes(q.tab)?q.tab:'documents';browseLatest.value=!q.snapshot||q.latest==='1'||!app;search.value=String(q.q||'');group.value=String(q.group||'');maintainer.value=String(q.maintainer||'');if(!app&&q.snapshot&&q.detail_service&&services.value.some(s=>s.name===q.detail_service)&&(!document.value||snapshot.value!==Number(q.snapshot)||detailService.value!==q.detail_service)){service.value='';environment.value=env;view.value='documents';snapshots.value=[];snapshot.value=null;document.value=null;selected.value=null;await openSearchResult({service:q.detail_service,snapshot_id:Number(q.snapshot),id:q.operation},'view',false);return}if(protocolChanged||app!==service.value||env!==environment.value){epoch++;service.value=app;environment.value=env;view.value=tab;snapshots.value=[];snapshot.value=null;document.value=null;selected.value=null;detailLoading.value=false;await loadSnapshots(q.snapshot,q.operation)}else if(app&&q.snapshot&&Number(q.snapshot)!==snapshot.value){snapshot.value=Number(q.snapshot);view.value=tab;await loadDocument(q.operation)}else{view.value=tab;selected.value=document.value?.operations.find(o=>o.id===q.operation)||null}})
watch(view,()=>{if(service.value&&!loading.value&&!detailLoading.value)syncRoute()})
watch([search,group,maintainer],()=>{_view1.value=1;if(services.value.length&&!loading.value&&!detailLoading.value)syncRoute()})
onMounted(async()=>{try{const [list,user,envs]=await Promise.all([api('api/services'),api('/api/me'),api('api/environments')]);services.value=list;me.value=user;environments.value=envs;environment.value=environmentOptions.value.some(e=>e.value===route.query.environment)?route.query.environment:'__all';view.value=['history','impact'].includes(route.query.tab)?route.query.tab:'documents';service.value=services.value.some(s=>s.name===route.query.service)?route.query.service:'';if(service.value)await loadSnapshots(route.query.snapshot);else if(route.query.snapshot&&route.query.detail_service&&services.value.some(s=>s.name===route.query.detail_service))await openSearchResult({service:route.query.detail_service,snapshot_id:Number(route.query.snapshot),id:route.query.operation},'view',false);if(window.parent!==window)window.parent.postMessage({type:'context.visibility',service:false,environment:false},location.origin)}catch(e){toast(e.message,'error')}})


