<template><main class="api-center"><PageSurface :fill="latestList" :class="latestList?'p-4!':''"><PageHeader compact class="shrink-0 mb-3!" title="接口文档" help="可跨应用按功能名称、描述、路径和分组检索最新文档；应用是可选筛选。文档按应用、构建环境与制品保存不可变快照。开发和测试环境配置生成插件后可在构建中自动生成；变更历史只与同环境基线对比。环境地址与认证由接口测试复用。"><template #actions><Button v-if="protocol==='http'&&admin&&service&&concreteEnvironment" @click="openSource" variant="outline" size="default" type="button" :disabled="(!service||!concreteEnvironment)">文档来源</Button><div v-if="admin&&service&&concreteEnvironment" class="inline-flex min-w-0 items-center gap-2"><Input type="file" aria-label="选择上传文件" class="max-w-xs" accept=".json,application/json" :disabled="!service||!concreteEnvironment||importing" @change="e=>{for(const file of e.target.files||[])(importFile)(file);e.target.value=''}"/></div></template><template #context><span v-if="latestList&&searchTotal!==null" class="text-sm text-muted-foreground">共 {{searchTotal}} 个接口</span></template><template #filters v-if="!latestList"><OptionPicker :model-value="protocol" @update:model-value="selectProtocol" aria-label="文档协议" :disabled="saving||importing||sourceOpen" class="w-36" :options="[{value:'http',label:'HTTP'},{value:'dubbo',label:'Dubbo'}]"/><OptionPicker :model-value="service" @update:model-value="selectService" placeholder="全部应用" aria-label="文档所属应用" :disabled="saving||importing||sourceOpen" style="width:220px" :options="[{value:'',label:'全部应用'},...services.map(applicationOption)]"/><OptionPicker :model-value="environment" @update:model-value="selectEnvironment" :disabled="saving||importing||sourceOpen" aria-label="文档环境" style="width:180px" :options="environmentOptions"/></template></PageHeader><div v-if="lastReport" class="mb-4 flex flex-wrap items-center gap-3 text-sm" role="status"><Badge variant="secondary">{{reportStates[lastReport.state]}}</Badge><span>{{reportTime(lastReport.created_at)}} · {{lastReport.service}} / {{lastReport.environment}}</span><span v-if="lastReport.snapshot_id">文档 #{{lastReport.snapshot_id}}</span><span v-if="lastReport.changes">新增 {{lastReport.changes.added||0}} · 修改 {{lastReport.changes.modified||0}} · 删除 {{lastReport.changes.removed||0}}</span><Button variant="link" @click="openReport(lastReport.id)">查看本次上报</Button><Button variant="ghost" size="sm" @click="lastReport=null">关闭提示</Button></div><DocumentSearch :protocol="protocol" v-if="!service" v-model:search="search" v-model:group="group" v-model:maintainer="maintainer" :environment="environment" :services="services" :environments="environments" :opening="detailLoading" @open="openSearchResult" @total="searchTotal=$event"><template #scope><OptionPicker :model-value="service" @update:model-value="selectService" placeholder="全部应用" aria-label="文档所属应用" :disabled="saving||importing||sourceOpen" class="w-40 max-w-full" :options="[{value:'',label:'全部应用'},...services.map(applicationOption)]"/><OptionPicker :model-value="environment" @update:model-value="selectEnvironment" :disabled="saving||importing||sourceOpen" aria-label="文档环境" class="w-36 max-w-full" :options="environmentOptions"/></template><template #advanced><Field><FieldLabel>文档协议</FieldLabel><OptionPicker :model-value="protocol" @update:model-value="selectProtocol" aria-label="文档协议" :disabled="saving||importing||sourceOpen" class="w-full" :options="[{value:'http',label:'HTTP'},{value:'dubbo',label:'Dubbo'}]"/></Field></template></DocumentSearch><template v-else><Tabs :model-value="view" @update:model-value="view=$event;"><div class="flex min-w-0 items-center gap-2"><TabsList variant="line" class="h-auto! min-h-9 max-w-full flex-wrap justify-start gap-x-3 gap-y-1 [&>[data-slot=tabs-trigger]]:h-9 [&>[data-slot=tabs-trigger]]:flex-none"><TabsTrigger :value="&quot;documents&quot;">接口列表</TabsTrigger><TabsTrigger :value="&quot;history&quot;">变更历史</TabsTrigger><TabsTrigger :value="&quot;impact&quot;">用例影响</TabsTrigger></TabsList></div><TabsContent :value="&quot;documents&quot;" force-mount v-show="!(view!==&quot;documents&quot;)" class="