ed-lg border" :style="{maxHeight:({x:700}).y?({x:700}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:1000}).x||({x:1000}).minWidth||1000)+'px'}"><TableHeader class="bg-muted/50"><TableRow><TableHead :style="{width:(380)+'px'}">接口名称 / 路径</TableHead><TableHead :style="{width:(100)+'px'}">方法</TableHead><TableHead :style="{width:(90)+'px'}">类型</TableHead><TableHead>分组</TableHead><TableHead :style="{width:(230)+'px'}">操作</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (operations||[]).slice((_view1-1)*(({pageSize:15,showTotal:true}).pageSize||10),_view1*(({pageSize:15,showTotal:true}).pageSize||10))" :key="typeof (&quot;id&quot;)==='function'?(&quot;id&quot;)(record):record[&quot;id&quot;]??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><Button @click="showOperation(record)" class="operation-name" variant="ghost" size="default" type="button">{{record.summary||record.path}}</Button><div class="operation-path">{{record.path}}</div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><Badge :variant="(record.method==='GET'?'blue':'green')==='red'?'destructive':'secondary'">{{record.method}}</Badge></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]">{{record.sse?'SSE':'HTTP'}}</template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]">{{record.tags?.join(' / ')||'—'}}</template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><Button @click="showOperation(record)" variant="ghost" size="default" type="button">查看</Button><Button @click="openTesting(record)" variant="ghost" size="default" type="button">调试</Button><Button @click="openTesting(record,'test-cases')" variant="ghost" size="default" type="button">生成用例</Button></template></div></TableCell></TableRow></template><TableRow v-if="!(operations||[]).length"><TableCell :colspan="5"><Empty><EmptyHeader><EmptyDescription>{{snapshots.length?'没有匹配的接口':protocol==='dubbo'?'暂无 Dubbo 文档，可导入 Dubbo JSON 文档':'暂无文档，可导入 OpenAPI 或绑定文档生成插件'}}</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div><div class="flex flex-wrap items-center justify-end gap-3 py-4"><span class="mr-auto text-sm text-muted-foreground">共 {{(operations||[]).length}} 项</span><Pagination class="mx-0 w-auto" :page="_view1" :total="(operations||[]).length" :items-per-page="({pageSize:15,showTotal:true}).pageSize||10" @update:page="_view1=$event;"><PaginationContent><PaginationPrevious/><span class="px-2 text-sm">{{_view1}} / {{Math.max(1,Math.ceil(((operations||[]).length)/(({pageSize:15,showTotal:true}).pageSize||10)))}}</span><PaginationNext/></PaginationContent></Pagination></div></div></template></template></template></PageSurface><Sheet :open="!!selected" @update:open="async v=>{if(!v){closeOperation()}}"><SheetContent class="data-[side=right]:w-full gap-0 overflow-hidden p-0 data-[side=right]:sm:max-w-[var(--editor-width)]" :class="false?'inset-0 h-dvh max-h-dvh w-screen max-w-none translate-x-0 translate-y-0 rounded-none sm:max-w-none':''" :style="{'--editor-width':typeof ('min(1100px, 100vw)')==='number'?('min(1100px, 100vw)')+'px':('min(1100px, 100vw)')}" :show-close-button="!editorState.busy" @escape-key-down="event=>{if(editorState.busy)event.preventDefault()}" @interact-outside="e=>{e.preventDefault()}"><SheetHeader class="shrink-0 border-b p-5 pr-12"><SheetTitle>{{editingDoc?'编辑接口文档':selected?.summary||selected?.path}}</SheetTitle><SheetDescription class="sr-only">详情与操作</SheetDescription></SheetHeader><div ref="documentContent" v-show="!editingDoc" class="min-h-0 flex-1 overflow-auto p-5"><template v-if="selected"><div class="snapshot-meta"><Badge variant="outline">{{detailApplication}} · {{detailEnvironment}} · 快照 #{{snapshot}}</Badge><Badge variant="secondary">{{selected.method}}</Badge><Button variant="ghost" size="sm" class="h-auto min-w-0 max-w-full justify-start whitespace-normal break-all px-0 py-0 text-left font-mono text-xs text-muted-foreground select-text" data-document-copy-include :aria-label="selected.protocol==='dubbo'?'复制方法签名':'复制接口 URL'" :title="selected.protocol==='dubbo'?'点击复制方法签名':'点击复制接口 URL'" @click="copyInterfaceURL">{{displayURL}}</Button><Badge v-if="selected.sse" :variant="(&quot;blue&quot;)==='red'?'destructive':'secondary'">SSE</Badge></div><OperationUpdates :info="document.update_info" :service="detailService" :environment="current?.environment" :protocol="protocol" :snapshot="document.id" :operation="selected.id"/><DocumentProvenance :lineage="document.lineage" :error="document.lineage_error" :operation="selected.id" :snapshot="document.id"/><div class="document-toolbar" data-document-copy-ignore><Button @click="openTesting(selected)" variant="default">调试接口</Button><Button v-if="admin&&current?.environment" @click="editingDoc=true" variant="outline">编辑接口</Button><Button @click="copyCurrentDocument" variant="outline">复制当前内容</Button><DropdownMenu><DropdownMenuTrigger as-child><Button variant="outline">更多</Button></DropdownMenuTrigger><DropdownMenuContent align="start"><DropdownMenuItem @select="openTesting(selected,'test-cases')">生成用例</DropdownMenuItem></DropdownMenuContent></DropdownMenu></div><div class="my-3 flex min-w-0 items-start gap-2 text-sm"><span class="shrink-0 text-muted-foreground">维护人</span><span class="min-w-0 whitespace-normal [overflow-wrap:anywhere]">{{selected.maintainer_name||selected.maintainer||'未填写'}}</span></div><p v-if="document.field_additions_error" role="alert" class="my-3 text-sm text-destructive">新增字段分析未完成：{{document.field_additions_error}}；完整文档仍可查看、复制。</p><section v-if="addedFields.length" class="my-4 rounded-lg border px-3 text-sm"><Accordion type="single" collapsible><AccordionItem value="added-fields"><AccordionTrigger>本次新增字段（{{addedFields.length}}） · 相对{{current.baseline_id?'修订 #'+current.baseline_id:'首次空基线'}}</AccordionTrigger><AccordionContent><div v-for="field in addedFields" :key="[field.operation,field.in,field.status,field.media,field.name].join('|')" class="mt-2 flex flex-wrap gap-2"><Badge variant="outline">新增</Badge><span>{{field.in==='response'?'响应 '+field.status:field.in}} · {{field.name}}</span><span>{{field.work_item?'#'+(field.work_item.external_id||field.work_item.id)+' · '+field.work_item.title:'未关联需求'}}</span></div></AccordionContent></AccordionItem></Accordion></section><MarkdownContent v-if="selected.description" :content="selected.description" label="接口说明"/><DubboOperation v-if="selected.protocol==='dubbo'" :operation="selected" :document="contract"/><Tabs v-else :model-value="_view2" @update:model-value="_view2=$event"><div class="flex min-w-0 items-center gap-2"><TabsList class="h-auto! max-w-full flex-wrap gap-y-1 [&>[data-slot=tabs-trigger]]:h-7"><TabsTrigger :value="&quot;request&quot;">请求参数</TabsTrigger><TabsTrigger :value="&quot;responses&quot;">响应定义</TabsTrigger><TabsTrigger :value="&quot;raw&quot;">原始定义</TabsTrigger></TabsList></div><TabsContent :value="&quot;request&quot;" force-mount v-show="!(_view2!==&quot;request&quot;)" class="min-w-0"><OptionPicker v-if="Object.keys(requestContent).length" v-model="requestMime" aria-label="请求正文类型" style="width:260px;margin-bottom:12px" :options="Object.keys(requestContent)"/><SchemaView :key="'params:'+detailService+':'+snapshot+':'+selected.id" v-if="parameters.length" :rows="parameters" :changes="fieldChanges()" :schema="parameterSchema" :definition="operationParameters({...selected,definition},contract)" :docum