mplate></div><component :is="selected.protocol==='dubbo'?DubboDocumentEditor:DocumentEditor" :work-item="route.query.work_item" v-if="editingDoc" ref="documentEditor" :text="document.document_text" :source="current" :operation="selected.id" @state="editorState=$event" @cancel="editingDoc=false;editorState={dirty:false,busy:false}" @saved="documentSaved"/></SheetContent></Sheet><Dialog :open="sourceOpen" @update:open="async v=>{if(!v){sourceOpen=false;}}"><DialogContent class="flex max-h-[92dvh] flex-col gap-0 overflow-hidden p-0 sm:max-w-[var(--editor-width)]" :class="false?'inset-0 h-dvh max-h-dvh w-screen max-w-none translate-x-0 translate-y-0 rounded-none sm:max-w-none':''" :style="{'--editor-width':typeof (620)==='number'?(620)+'px':(620)}" :show-close-button="!saving" @interact-outside="e=>{if(!(!saving))e.preventDefault()}"><DialogHeader class="shrink-0 border-b p-5 pr-12"><DialogTitle>{{'文档来源 · '+(environments.find(e=>e.name===environment)?.display_name||environment)}}</DialogTitle><DialogDescription class="sr-only">详情与操作</DialogDescription></DialogHeader><div class="min-h-0 flex-1 overflow-auto p-5"><fieldset :disabled="saving||schemaLoading" class="min-w-0 space-y-5" ><Field><FieldLabel>生成插件</FieldLabel><OptionPicker :model-value="source.provider" @update:model-value="changeProvider" aria-label="文档生成插件" class="min-w-36" :options="[{value:'',label:'仅手动导入'},...providers.map(p=>({value:p.manifest.id,label:p.manifest.name+(p.state==='running'?'':'（未启用）'),disabled:p.state!=='running'}))]"/></Field><div style="width:100%" class="relative min-w-0" :aria-busy="schemaLoading"><div v-if="schemaLoading" class="flex items-center justify-center gap-2 p-4" role="status"><Spinner/><span class="sr-only">正在读取</span></div><Field v-for="field in fields" :key="field.key"><FieldLabel>{{field.label}} <HelpTip v-if="field.help" :text="field.help"/></FieldLabel><Input v-model="source.settings[field.key]" :aria-label="field.label"/></Field></div><template v-if="source.provider"><Field><FieldLabel>构建时自动生成</FieldLabel><Switch v-model="source.on_build"/><HelpTip text="按环境保存。开发和测试环境选择生成插件后默认启用；只有本次构建目标环境匹配时才自动生成。编排插件节点也引用当前环境的来源。"/></Field><Field v-if="source.on_build"><FieldLabel>生成失败阻止构建就绪</FieldLabel><Switch v-model="source.required"/></Field></template></fieldset></div><DialogFooter class="shrink-0 flex-wrap border-t p-4"><Button variant="outline" @click="async()=>{sourceOpen=false;}" :disabled="({disabled:saving}).disabled">取消</Button><Button :disabled="saving" @click="async()=>{if(await (async()=>{await saveSource();return false})()!==false){sourceOpen=false;}}"><Spinner v-if="saving"/>确认</Button></DialogFooter></DialogContent></Dialog></main></template>
<style scoped>.api-center{height:100dvh;min-width:0;width:100%;overflow:auto;box-sizing:border-box;background:var(--bg);color:var(--text)}.document-toolbar{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:16px}.snapshot-meta{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:12px 0 20px;color:var(--muted-foreground);font-size:.75rem;overflow-wrap:anywhere}.operation-name{max-width:100%;white-space:normal;text-align:left}.operation-path{font-family:var(--mono);font-size:.75rem;color:var(--muted-foreground);overflow-wrap:anywhere}.response-title{display:flex;gap:8px;align-items:center;margin:16px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:var(--panel2);padding:16px;font-family:var(--mono);font-size:.75rem}</style>
